'use client';

import {
  AnimatePresence,
  motion,
  useInView,
  type Transition,
  type Variants,
} from 'motion/react';
import { useId, useRef, useState } from 'react';

import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { QuoteIcon } from '@/registry/ndeko/lib/icons';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { CarouselControls, tabIdOf } from './carousel-controls';
import { SECTION, SLIDES } from './data';
import { QuoteSlide } from './quote-slide';
import { useSlideClock } from './use-slide-clock';

type Direction = 1 | -1;

/** `auto` turns unless the system asks for reduced motion; a person's Play or Pause decides from then on. */
type Rotation = 'auto' | 'on' | 'off';

const SLIDE_MS = 7000;

const TRAVEL_PX = 24;

const BLURRED = 'blur(4px)';

const ENTER: Transition = { duration: 0.4, ease: EASE_OUT_STRONG };

const EXIT: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

function enteringOf(direction: Direction) {
  const x = direction * TRAVEL_PX;
  return { opacity: 0, x, filter: BLURRED };
}

function leavingOf(direction: Direction) {
  const x = direction * -TRAVEL_PX;
  return { opacity: 0, x, filter: BLURRED, transition: EXIT };
}

const SLIDE_VARIANTS: Variants = {
  enter: enteringOf,
  shown: { opacity: 1, x: 0, filter: 'blur(0px)', transition: ENTER },
  gone: leavingOf,
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  shown: { opacity: 1, transition: ENTER },
  gone: { opacity: 0, transition: EXIT },
};

function variantsOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SLIDE_VARIANTS;
}

function isRotationOn(rotation: Rotation, shouldReduceMotion: boolean) {
  if (rotation === 'auto') {
    return !shouldReduceMotion;
  }
  return rotation === 'on';
}

function indexAfter(index: number) {
  const next = index + 1;
  return next % SLIDES.length;
}

function indexBefore(index: number) {
  const shifted = index + SLIDES.length;
  const previous = shifted - 1;
  return previous % SLIDES.length;
}

function directionBetween(from: number, to: number): Direction {
  if (to < from) {
    return -1;
  }
  return 1;
}

function spokenSlideOf(index: number) {
  const { person } = SLIDES[index];
  const position = index + 1;
  return `Quote ${position} of ${SLIDES.length}, ${person.name}, ${person.role} at ${person.company}`;
}

const SLIDE_SECONDS = SLIDE_MS / 1000;

const PLAYING_LINE = `Quotes play again, a new one every ${SLIDE_SECONDS} seconds`;

export default function Testimonials02() {
  const [activeIndex, setActiveIndex] = useState(0);
  const [direction, setDirection] = useState<Direction>(1);
  const [rotation, setRotation] = useState<Rotation>('auto');
  const [isHovered, setIsHovered] = useState(false);
  const [isFocusHeld, setIsFocusHeld] = useState(false);
  const [message, setMessage] = useState('');
  const stageRef = useRef<HTMLDivElement>(null);
  const fillRef = useRef<HTMLSpanElement>(null);
  const idBase = useId();
  const shouldReduceMotion = usePrefersReducedMotion();
  const isInView = useInView(stageRef, { amount: 0.3 });
  const isTabVisible = useDocumentVisible();
  const isRotating = isRotationOn(rotation, shouldReduceMotion);
  const isOnScreen = isInView && isTabVisible;
  const isHeld = isHovered || isFocusHeld;
  const canTurn = isRotating && isOnScreen;
  const isClockRunning = canTurn && !isHeld;
  const activeSlide = SLIDES[activeIndex];
  const panelId = `${idBase}-panel`;
  const activeTabId = tabIdOf(idBase, activeSlide.id);
  const variants = variantsOf(shouldReduceMotion);

  function show(index: number, nextDirection: Direction) {
    setDirection(nextDirection);
    setActiveIndex(index);
  }

  function turn() {
    show(indexAfter(activeIndex), 1);
  }

  useSlideClock(fillRef, {
    slideKey: activeSlide.id,
    isRotating,
    isRunning: isClockRunning,
    durationMs: SLIDE_MS,
    onEnd: turn,
  });

  function showByPerson(index: number, nextDirection: Direction) {
    setRotation('off');
    show(index, nextDirection);
    setMessage(spokenSlideOf(index));
  }

  function showPrevious() {
    showByPerson(indexBefore(activeIndex), -1);
  }

  function showNext() {
    showByPerson(indexAfter(activeIndex), 1);
  }

  function pick(slideId: string) {
    const index = SLIDES.findIndex((slide) => slide.id === slideId);
    const isCurrent = index === activeIndex;
    if (isCurrent) {
      return;
    }
    showByPerson(index, directionBetween(activeIndex, index));
  }

  /** Play while the keyboard is inside would otherwise wait for the focus to leave. */
  function toggleRotation() {
    if (isRotating) {
      setRotation('off');
      setMessage('Quotes paused');
      return;
    }
    setRotation('on');
    setIsFocusHeld(false);
    setMessage(PLAYING_LINE);
  }

  function holdOnKeyboardFocus(event: React.FocusEvent<HTMLElement>) {
    const isKeyboardFocus = event.target.matches(':focus-visible');
    if (isKeyboardFocus) {
      setIsFocusHeld(true);
    }
  }

  function releaseWhenFocusLeaves(event: React.FocusEvent<HTMLElement>) {
    const next = event.relatedTarget;
    const staysInside = next !== null && event.currentTarget.contains(next);
    if (!staysInside) {
      setIsFocusHeld(false);
    }
  }

  function holdUnderPointer(event: React.PointerEvent<HTMLDivElement>) {
    if (event.pointerType === 'mouse') {
      setIsHovered(true);
    }
  }

  function releasePointer() {
    setIsHovered(false);
  }

  function stopRotation() {
    setRotation('off');
  }

  return (
    <section
      aria-roledescription='carousel'
      aria-label='Sample quotes from Fieldnote customers'
      onFocus={holdOnKeyboardFocus}
      onBlur={releaseWhenFocusLeaves}
      className='@container'
    >
      <div className='mx-auto flex max-w-4xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex max-w-2xl flex-col gap-3'>
          <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
            <QuoteIcon className='size-4' />
            {SECTION.label}
          </p>
          <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
            {SECTION.title}
          </h2>
          <p className='text-muted-foreground text-base text-pretty'>
            {SECTION.lead}
          </p>
        </header>
        <div className='flex flex-col gap-4'>
          <div
            ref={stageRef}
            onPointerEnter={holdUnderPointer}
            onPointerLeave={releasePointer}
            onPointerDown={stopRotation}
            className='bg-card hairline-ring ring-border dark:bg-foreground/[0.04] rounded-2xl p-6 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @2xl:p-10'
          >
            <div
              id={panelId}
              role='tabpanel'
              aria-roledescription='slide'
              aria-labelledby={activeTabId}
              className='grid *:col-start-1 *:row-start-1'
            >
              {SLIDES.map((slide) => (
                <div key={slide.id} aria-hidden='true' className='invisible'>
                  <QuoteSlide slide={slide} />
                </div>
              ))}
              <AnimatePresence initial={false} custom={direction}>
                <motion.div
                  key={activeSlide.id}
                  custom={direction}
                  variants={variants}
                  initial='enter'
                  animate='shown'
                  exit='gone'
                >
                  <QuoteSlide slide={activeSlide} />
                </motion.div>
              </AnimatePresence>
            </div>
          </div>
          <div className='flex flex-wrap items-center justify-between gap-3'>
            <CarouselControls
              slides={SLIDES}
              activeId={activeSlide.id}
              isRotating={isRotating}
              fillRef={fillRef}
              tabIdBase={idBase}
              panelId={panelId}
              onPick={pick}
              onPrevious={showPrevious}
              onNext={showNext}
              onToggleRotation={toggleRotation}
            />
            <Badge variant='secondary'>Sample quotes</Badge>
          </div>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';
import type { RefObject } from 'react';

import {
  ChevronLeftIcon,
  ChevronRightIcon,
  PauseIcon,
  PlayIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import type { Slide } from './data';

export function tabIdOf(base: string, slideId: string) {
  return `${base}-tab-${slideId}`;
}

function rotationLabelOf(isRotating: boolean) {
  if (isRotating) {
    return 'Pause the quotes';
  }
  return 'Play the quotes';
}

/** While the quotes turn, the bar of the current one fills from empty; at rest it is full. */
function fillTransformOf(isRotating: boolean) {
  if (isRotating) {
    return 'scaleX(0)';
  }
  return 'scaleX(1)';
}

function isSlideId(value: unknown, slides: readonly Slide[]) {
  return slides.some((slide) => slide.id === value);
}

type CarouselControlsProps = {
  slides: readonly Slide[];
  activeId: string;
  isRotating: boolean;
  fillRef: RefObject<HTMLSpanElement | null>;
  tabIdBase: string;
  panelId: string;
  onPick: (slideId: string) => void;
  onPrevious: () => void;
  onNext: () => void;
  onToggleRotation: () => void;
};

export function CarouselControls({
  slides,
  activeId,
  isRotating,
  fillRef,
  tabIdBase,
  panelId,
  onPick,
  onPrevious,
  onNext,
  onToggleRotation,
}: CarouselControlsProps) {
  const count = slides.length;
  const fillStyle = { transform: fillTransformOf(isRotating) };

  function pickTab(value: unknown) {
    if (isSlideId(value, slides)) {
      onPick(String(value));
    }
  }

  return (
    <div className='flex items-center gap-1'>
      <Button
        type='button'
        variant='ghost'
        size='icon-sm'
        aria-label={rotationLabelOf(isRotating)}
        onClick={onToggleRotation}
        className='text-muted-foreground'
      >
        <Swap swapKey={String(isRotating)}>
          {isRotating && <PauseIcon />}
          {!isRotating && <PlayIcon />}
        </Swap>
      </Button>
      <Button
        type='button'
        variant='outline'
        size='icon-sm'
        aria-label='Show the previous quote'
        onClick={onPrevious}
      >
        <ChevronLeftIcon />
      </Button>
      <TabsPrimitive.Root value={activeId} onValueChange={pickTab}>
        <TabsPrimitive.List
          activateOnFocus
          aria-label='Choose a quote'
          className='flex items-center px-1'
        >
          {slides.map((slide, index) => {
            const isActive = slide.id === activeId;
            const position = index + 1;

            return (
              <TabsPrimitive.Tab
                key={slide.id}
                value={slide.id}
                id={tabIdOf(tabIdBase, slide.id)}
                aria-controls={panelId}
                aria-label={`Quote ${position} of ${count}, ${slide.person.name}`}
                className='group/dot focus-visible:ring-ring focus-visible:ring-offset-background flex h-8 cursor-pointer items-center rounded-full px-1 outline-none focus-visible:ring-2 focus-visible:ring-offset-2'
              >
                <span className='bg-foreground/15 group-hover/dot:bg-foreground/25 group-data-active/dot:bg-foreground/20 relative h-1 w-6 overflow-hidden rounded-full transition-colors duration-150'>
                  {isActive && (
                    <span
                      ref={fillRef}
                      style={fillStyle}
                      className='bg-foreground absolute inset-0 origin-left rounded-full'
                    />
                  )}
                </span>
              </TabsPrimitive.Tab>
            );
          })}
        </TabsPrimitive.List>
      </TabsPrimitive.Root>
      <Button
        type='button'
        variant='outline'
        size='icon-sm'
        aria-label='Show the next quote'
        onClick={onNext}
      >
        <ChevronRightIcon />
      </Button>
    </div>
  );
}

import { Avatar } from '@/registry/ndeko/ui/avatar';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import type { QuotePart, Slide } from './data';

function QuotePartView({ part }: { part: QuotePart }) {
  if (part.kind === 'brand') {
    return (
      <span className='whitespace-nowrap'>
        <BrandTile
          brand={part.brand}
          size='md'
          className='me-1.5 align-[-0.15em]'
        />
        {part.text}
      </span>
    );
  }
  return part.text;
}

/** The person sits at the foot of the tallest slide, so their line stays put from one quote to the next. */
export function QuoteSlide({ slide }: { slide: Slide }) {
  const { person } = slide;

  return (
    <figure className='flex h-full flex-col justify-between gap-8'>
      <blockquote className='text-lg leading-8 font-medium text-pretty @2xl:text-2xl @2xl:leading-9'>
        <p>
          {slide.parts.map((part, index) => (
            <QuotePartView key={index} part={part} />
          ))}
        </p>
      </blockquote>
      <figcaption className='flex items-center gap-3'>
        <Avatar seed={person.name} className='size-10' />
        <span className='flex min-w-0 flex-1 flex-col'>
          <span className='truncate text-sm font-medium'>{person.name}</span>
          <span className='text-muted-foreground truncate text-[13px]'>
            {person.role}, {person.company}
          </span>
        </span>
        <CompanyMark seed={person.company} size='lg' />
      </figcaption>
    </figure>
  );
}

'use client';

import { useEffect, useEffectEvent, useRef, type RefObject } from 'react';

const FILL: Keyframe[] = [
  { transform: 'scaleX(0)' },
  { transform: 'scaleX(1)' },
];

type SlideClockOptions = {
  /** A new key starts a new fill: the slide changed. */
  slideKey: string;
  isRotating: boolean;
  /** False while the rotation is held: the fill stops where it is and goes on from there. */
  isRunning: boolean;
  durationMs: number;
  onEnd: () => void;
};

/**
 * The time a slide has left is the fill of its bar: a Web Animation on the compositor, so a slide
 * that waits costs no script at all, and a held one costs nothing. Its end moves the carousel on.
 */
export function useSlideClock<Fill extends HTMLElement>(
  fillRef: RefObject<Fill | null>,
  { slideKey, isRotating, isRunning, durationMs, onEnd }: SlideClockOptions
) {
  const animationRef = useRef<Animation | null>(null);
  const end = useEffectEvent(onEnd);

  useEffect(() => {
    const fill = fillRef.current;
    if (!fill || !isRotating) {
      return;
    }
    const animation = fill.animate(FILL, {
      duration: durationMs,
      easing: 'linear',
      fill: 'forwards',
    });
    animation.pause();
    animation.onfinish = () => end();
    animationRef.current = animation;
    return () => {
      animation.onfinish = null;
      animation.cancel();
      animationRef.current = null;
    };
  }, [fillRef, slideKey, isRotating, durationMs]);

  useEffect(() => {
    const animation = animationRef.current;
    if (!animation) {
      return;
    }
    const isPaused = animation.playState === 'paused';
    const isPlaying = animation.playState === 'running';
    if (isRunning && isPaused) {
      animation.play();
      return;
    }
    if (!isRunning && isPlaying) {
      animation.pause();
    }
  }, [isRunning, slideKey, isRotating]);
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export type QuotePart =
  | { kind: 'text'; text: string }
  | { kind: 'brand'; brand: BrandSlug; text: string };

export type Person = {
  name: string;
  role: string;
  company: string;
};

export type Slide = {
  id: string;
  parts: QuotePart[];
  person: Person;
};

export const SECTION = {
  label: 'Customer quotes',
  title: 'Teams that stopped taking meeting notes',
  lead: 'Fieldnote writes the summary while you talk and files each follow-up where it belongs.',
};

/** Invented people and companies. The quotes are samples written for this block. */
