        kind: 'text',
        text: ', writes the summary while we talk and has the follow-ups in ',
      },
      { kind: 'brand', brand: 'hubspot', text: 'HubSpot' },
      { kind: 'text', text: ' before I close the tab.' },
    ],
    person: {
      name: 'Ines Carvalho',
      role: 'Account director',
      company: 'Harbourline Logistics',
    },
  },
  {
    id: 'rafael',
    parts: [
